@@ -0,0 +1,20 @@
+package hotel.messages;
+
+import java.util.List;
+
+public final class EmailValidationRule implements MessageRule {
+
+    private final EmailValidator validator;
+
+    public EmailValidationRule(EmailValidator validator) {
+        this.validator = validator;
+    }
+
+    @Override
+    public List<OutgoingMessage> apply(OutgoingMessage message) {
+        if (!validator.isValid(message.to())) {
+            message.setStatus(MessageStatus.BLOCKED);
+        }
+        return List.of(message);
+    }
+}
diff --git a/src/main/java/hotel/messages/EmailValidator.java b/src/main/java/hotel/messages/EmailValidator.java
new file mode 100644
index 0000000..cb561ab
--- /dev/null
+++ b/src/main/java/hotel/messages/EmailValidator.java
@@ -0,0 +1,20 @@
+package hotel.messages;
+
+public final class EmailValidator {
+
+    public boolean isValid(String email) {
+        if (email == null || email.isBlank()) {
+            return false;
+        }
+        int atIndex = email.indexOf('@');
+        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
+            return false;
+        }
+        String localPart = email.substring(0, atIndex);
+        String domainPart = email.substring(atIndex + 1);
+        if (localPart.isEmpty() || domainPart.isEmpty()) {
+            return false;
+        }
+        return domainPart.contains(".");
+    }
+}
